    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    wire [4:0] sum_temp;
    reg  [3:0] bcd_sum;
    reg        carry_out;

    assign sum_temp = A + B + Cin;

    always @(*) begin
        if (sum_temp > 9) begin
            bcd_sum = sum_temp - 10;
            carry_out = 1'b1;
        end else begin
            bcd_sum = sum_temp[3:0];
            carry_out = 1'b0;
        end
    end

    assign Sum = bcd_sum;
    assign Cout = carry_out;

endmodule

